  "updated_time" timestamp(6) NOT NULL,
  "created_id" int4,
  "updated_id" int4
)
;
COMMENT ON COLUMN "public"."task_workflow_node_type"."name" IS '显示名称';
COMMENT ON COLUMN "public"."task_workflow_node_type"."code" IS '节点编码，对应画布 node.type';
